import type { NextFunction, Request, Response } from 'express';
import jwt, {
  JsonWebTokenError,
  NotBeforeError,
  TokenExpiredError,
  type JwtPayload,
} from 'jsonwebtoken';

export class AuthError extends Error {
  readonly statusCode: number;
  readonly code: string;

  constructor(message: string, statusCode = 401, code = 'AUTH_ERROR') {
    super(message);
    this.name = 'AuthError';
    this.statusCode = statusCode;
    this.code = code;
  }
}

export class MissingAuthHeaderError extends AuthError {
  constructor() {
    super('Authorization header is required', 401, 'MISSING_AUTH_HEADER');
    this.name = 'MissingAuthHeaderError';
  }
}

export class InvalidAuthHeaderError extends AuthError {
  constructor() {
    super('Authorization header must use Bearer scheme', 401, 'INVALID_AUTH_HEADER');
    this.name = 'InvalidAuthHeaderError';
  }
}

export class InvalidTokenError extends AuthError {
  constructor(message = 'Invalid authentication token') {
    super(message, 401, 'INVALID_TOKEN');
    this.name = 'InvalidTokenError';
  }
}

export class ExpiredTokenError extends AuthError {
  constructor() {
    super('Authentication token has expired', 401, 'TOKEN_EXPIRED');
    this.name = 'ExpiredTokenError';
  }
}

export interface AuthenticatedRequest extends Request {
  user?: string | JwtPayload;
  token?: string;
}

function getBearerToken(authorization?: string): string {
  if (!authorization) {
    throw new MissingAuthHeaderError();
  }

  const [scheme, token, ...rest] = authorization.trim().split(/\s+/);

  if (scheme !== 'Bearer' || !token || rest.length > 0) {
    throw new InvalidAuthHeaderError();
  }

  if (!token.trim()) {
    throw new InvalidTokenError('Bearer token is empty');
  }

  return token;
}

export function authMiddleware(secret: string) {
  if (!secret) {
    throw new Error('JWT secret is not configured');
  }

  return (req: AuthenticatedRequest, _res: Response, next: NextFunction) => {
    try {
      const token = getBearerToken(req.header('authorization'));

      const payload = jwt.verify(token, secret, {
        algorithms: ['HS256'], // restrict algorithms explicitly
      });

      req.token = token;
      req.user = payload;

      return next();
    } catch (error) {
      if (error instanceof TokenExpiredError) {
        return next(new ExpiredTokenError());
      }

      if (error instanceof JsonWebTokenError || error instanceof NotBeforeError) {
        return next(new InvalidTokenError(error.message));
      }

      if (error instanceof AuthError) {
        return next(error);
      }

      return next(new AuthError('Authentication failed'));
    }
  };
}
```

